insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6a8554d1-b857-56ec-9f71-f4d324fc1c52', 'RNA polymerase unwinds the DNA and separates the strands by breaking hydrogen bonds [1]; it uses one strand as a template so RNA nucleotides pair with complementary bases [1]; it joins the RNA nucleotides together with covalent bonds to make the mRNA strand [1].', 'RNA polymerase unwinds the DNA and separates the strands by breaking hydrogen bonds [1]; it uses one strand as a template so RNA nucleotides pair with complementary bases [1]; it joins the RNA nucleotides together with covalent bonds to make the mRNA strand [1].', '[{"text": "Marking point 1", "any": ["unwind", "separate", "hydrogen bonds"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["template", "complementary"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["join", "link", "covalent", "bonds rna nucleotides"], "all": [], "marks": 1}]'::jsonb, 'RNA polymerase unwinds the DNA and separates the strands by breaking hydrogen bonds [1]; it uses one strand as a template so RNA nucleotides pair with complementary bases [1]; it joins the RNA nucleotides together with covalent bonds to make the mRNA strand [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
