insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ac4253fd-f175-5d20-8127-3a90cd36a105', 'A base substitution changes the codon GAG to GUG in the mRNA [1]; so glutamic acid [1] is replaced by valine in the β chain of haemoglobin [1]; the altered haemoglobin forms fibres at low O₂, giving sickle-shaped red blood cells that block capillaries [1].', 'A base substitution changes the codon GAG to GUG in the mRNA [1]; so glutamic acid [1] is replaced by valine in the β chain of haemoglobin [1]; the altered haemoglobin forms fibres at low O₂, giving sickle-shaped red blood cells that block capillaries [1].', '[{"text": "Marking point 1", "any": ["codon changes", "a to t", "cac"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["glutamic", "glutamate"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["valine"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["sickle", "stick together", "fibres", "insoluble"], "all": [], "marks": 1}]'::jsonb, 'A base substitution changes the codon GAG to GUG in the mRNA [1]; so glutamic acid [1] is replaced by valine in the β chain of haemoglobin [1]; the altered haemoglobin forms fibres at low O₂, giving sickle-shaped red blood cells that block capillaries [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('14905e41-835b-56c9-bbca-cad84fa4b6bd', 'ac4253fd-f175-5d20-8127-3a90cd36a105', 26);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('4dd7b6d7-6619-5e46-99e0-300e62ce11d4', 'short', 'Explain why the genetic code is described as a triplet code and as degenerate.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('4dd7b6d7-6619-5e46-99e0-300e62ce11d4', 'Each codon has three bases [1]; 4³ = 64 codons, more than enough for 20 amino acids [1]; so most amino acids are coded for by more than one codon, which is why it is degenerate [1].', 'Each codon has three bases [1]; 4³ = 64 codons, more than enough for 20 amino acids [1]; so most amino acids are coded for by more than one codon, which is why it is degenerate [1].', '[{"text": "Marking point 1", "any": ["three bases", "3 bases"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["64", "20"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["more than one codon", "several codons", "same amino acid"], "all": [], "marks": 1}]'::jsonb, 'Each codon has three bases [1]; 4³ = 64 codons, more than enough for 20 amino acids [1]; so most amino acids are coded for by more than one codon, which is why it is degenerate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
