insert into public.questions (id, kind, prompt, options, marks, image_url) values ('c1d1fdbe-9428-5ac8-94a5-167b8daaccd5', 'short', 'Explain why an insertion of one base usually has a greater effect than a substitution.', '[]'::jsonb, 3, 'https://commons.wikimedia.org/wiki/Special:FilePath/Deletion_Insertion_Substitution-en.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c1d1fdbe-9428-5ac8-94a5-167b8daaccd5', 'An insertion shifts the reading frame (frameshift) [1]; so every codon after it is changed, altering many amino acids or creating an early stop, so the polypeptide is unlikely to work [1]; a substitution changes only one codon, which may give one different amino acid or none at all because the code is degenerate [1].', 'An insertion shifts the reading frame (frameshift) [1]; so every codon after it is changed, altering many amino acids or creating an early stop, so the polypeptide is unlikely to work [1]; a substitution changes only one codon, which may give one different amino acid or none at all because the code is degenerate [1].', '[{"text": "Marking point 1", "any": ["frameshift", "reading frame", "shift"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["every codon", "all codons", "all following", "after the mutation", "downstream"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["only one codon", "one amino acid", "degenera", "silent"], "all": [], "marks": 1}]'::jsonb, 'An insertion shifts the reading frame (frameshift) [1]; so every codon after it is changed, altering many amino acids or creating an early stop, so the polypeptide is unlikely to work [1]; a substitution changes only one codon, which may give one different amino acid or none at all because the code is degenerate [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
