insert into public.questions (id, kind, prompt, options, marks, image_url) values ('6f70897d-6d80-5af9-b5f1-45a43a8a68b9', 'short', 'In a greenhouse, raising CO₂ from 400 to 800 ppm increased tomato yield by 30% in winter but only 5% on very hot summer days. Suggest reasons for the difference.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6f70897d-6d80-5af9-b5f1-45a43a8a68b9', 'In winter, CO₂ was the limiting factor, so adding CO₂ greatly increased photosynthesis and yield [1]; on hot summer days, high temperature limits the rate (enzymes near or above the optimum) [1]; also stomata may close to save water, so extra CO₂ cannot enter / another factor limits [1].', 'In winter, CO₂ was the limiting factor, so adding CO₂ greatly increased photosynthesis and yield [1]; on hot summer days, high temperature limits the rate (enzymes near or above the optimum) [1]; also stomata may close to save water, so extra CO₂ cannot enter / another factor limits [1].', '[{"text": "Marking point 1", "any": ["carbon dioxide was limiting", "limiting in winter"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["too hot", "high temperature", "denature"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["water", "stomata", "light", "other factor"], "all": [], "marks": 1}]'::jsonb, 'In winter, CO₂ was the limiting factor, so adding CO₂ greatly increased photosynthesis and yield [1]; on hot summer days, high temperature limits the rate (enzymes near or above the optimum) [1]; also stomata may close to save water, so extra CO₂ cannot enter / another factor limits [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('dbe8f1a7-5413-5beb-afd8-aa3097a6487e', '6f70897d-6d80-5af9-b5f1-45a43a8a68b9', 23);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('9dd8092e-e90a-55d4-a594-08b9c3785f7c', 'short', 'Explain the advantages of having many pigment molecules arranged in a photosystem.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('9dd8092e-e90a-55d4-a594-08b9c3785f7c', 'Many different pigments absorb more light over a wider range of wavelengths [1]; absorbed energy is passed from pigment to pigment and funnelled to the special chlorophyll in the reaction centre [1]; the reaction centre emits an excited electron to a specific acceptor, so the energy is used rather than lost as heat or fluorescence [1].', 'Many different pigments absorb more light over a wider range of wavelengths [1]; absorbed energy is passed from pigment to pigment and funnelled to the special chlorophyll in the reaction centre [1]; the reaction centre emits an excited electron to a specific acceptor, so the energy is used rather than lost as heat or fluorescence [1].', '[{"text": "Marking point 1", "any": ["more light", "more wavelengths", "range of wavelengths", "wider range", "absorb more"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["funnel", "passed to", "reaction centre"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["acceptor", "not lost", "excited electron", "emit"], "all": [], "marks": 1}]'::jsonb, 'Many different pigments absorb more light over a wider range of wavelengths [1]; absorbed energy is passed from pigment to pigment and funnelled to the special chlorophyll in the reaction centre [1]; the reaction centre emits an excited electron to a specific acceptor, so the energy is used rather than lost as heat or fluorescence [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
