insert into public.questions (id, kind, prompt, options, marks, image_url) values ('d6929d7c-4101-5537-ae43-c7019a3e3bbf', 'short', 'Explain how ATP is produced in the thylakoid.', '[]'::jsonb, 4, 'https://commons.wikimedia.org/wiki/Special:FilePath/Thylakoid_membrane_3.svg?width=900') on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d6929d7c-4101-5537-ae43-c7019a3e3bbf', 'Excited electrons from the photosystems pass along the electron transport chain [1]; energy released is used to pump protons into the thylakoid lumen [1]; creating a proton gradient (high concentration in the lumen) [1]; protons diffuse back into the stroma through ATP synthase, which makes ATP (chemiosmosis / photophosphorylation) [1].', 'Excited electrons from the photosystems pass along the electron transport chain [1]; energy released is used to pump protons into the thylakoid lumen [1]; creating a proton gradient (high concentration in the lumen) [1]; protons diffuse back into the stroma through ATP synthase, which makes ATP (chemiosmosis / photophosphorylation) [1].', '[{"text": "Marking point 1", "any": ["excited electron", "electrons", "electron transport chain"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["pump", "pumped"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["gradient", "high concentration", "lumen"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["atp synthase", "chemiosmosis", "flow back"], "all": [], "marks": 1}]'::jsonb, 'Excited electrons from the photosystems pass along the electron transport chain [1]; energy released is used to pump protons into the thylakoid lumen [1]; creating a proton gradient (high concentration in the lumen) [1]; protons diffuse back into the stroma through ATP synthase, which makes ATP (chemiosmosis / photophosphorylation) [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('dbe8f1a7-5413-5beb-afd8-aa3097a6487e', 'd6929d7c-4101-5537-ae43-c7019a3e3bbf', 28);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('fbaf1a1e-3873-5576-8d43-095a37d1db31', 'short', 'Compare cyclic and non-cyclic photophosphorylation.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('fbaf1a1e-3873-5576-8d43-095a37d1db31', 'Both produce ATP by chemiosmosis [1]; cyclic uses only PSI, with electrons returning to PSI, while non-cyclic uses PSII and PSI [1]; non-cyclic also reduces NADP and releases oxygen from photolysis; cyclic does neither [1].', 'Both produce ATP by chemiosmosis [1]; cyclic uses only PSI, with electrons returning to PSI, while non-cyclic uses PSII and PSI [1]; non-cyclic also reduces NADP and releases oxygen from photolysis; cyclic does neither [1].', '[{"text": "Marking point 1", "any": ["both make atp"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["only photosystem i", "only psi"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["no nadp", "no oxygen", "oxygen"], "all": [], "marks": 1}]'::jsonb, 'Both produce ATP by chemiosmosis [1]; cyclic uses only PSI, with electrons returning to PSI, while non-cyclic uses PSII and PSI [1]; non-cyclic also reduces NADP and releases oxygen from photolysis; cyclic does neither [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('dbe8f1a7-5413-5beb-afd8-aa3097a6487e', 'fbaf1a1e-3873-5576-8d43-095a37d1db31', 29);
insert into public.questions (id, kind, prompt, options, marks, image_url) values ('41aede1d-c158-5934-bfa0-3fc76fb06865', 'short', 'Outline the consequences for living organisms and for Earth of oxygen generation by photolysis.', '[]'::jsonb, 3, null) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind, image_url = excluded.image_url;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('41aede1d-c158-5934-bfa0-3fc76fb06865', 'Oxygen accumulated in the atmosphere [1]; an ozone layer formed, shielding the surface from UV so life could colonise land [1]; dissolved iron was oxidised and deposited as banded iron rocks; aerobic respiration and larger organisms evolved while many anaerobes died out [1].', 'Oxygen accumulated in the atmosphere [1]; an ozone layer formed, shielding the surface from UV so life could colonise land [1]; dissolved iron was oxidised and deposited as banded iron rocks; aerobic respiration and larger organisms evolved while many anaerobes died out [1].', '[{"text": "Marking point 1", "any": ["atmosphere", "oxygen-rich", "oxygen in the air"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["ozone", "uv"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["iron", "rock", "banded", "aerobic", "extinction", "anaerobes"], "all": [], "marks": 1}]'::jsonb, 'Oxygen accumulated in the atmosphere [1]; an ozone layer formed, shielding the surface from UV so life could colonise land [1]; dissolved iron was oxidised and deposited as banded iron rocks; aerobic respiration and larger organisms evolved while many anaerobes died out [1].') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
